INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_CHR_ANGELS_DIONYS','ENT_CHR_ANGELS','SRC_PSEUDO_DIONYSIUS_CELESTIAL_HIERARCHY','Pseudo-Dionysius, The Celestial Hierarchy','Pseudo-Dionysius, The Celestial Hierarchy','Paul his " chief initiator," and as such, gives his teaching on the holy Angels, in the sixth chapter of the Heavenly Hierarchy; and frequently describes St. Paul as his " chief instructor." If, then, we can prove that the writings of Diony- and the Alexandrine School.','John Parker',1897,'https://archive.org/details/theworksofdionys00dionuoft',NULL,'primary-verbatim',NULL,true,'OCR scan, located by name; verify chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CHR_ARCHANGELS_DIONYS','ENT_CHR_ARCHANGELS','SRC_PSEUDO_DIONYSIUS_CELESTIAL_HIERARCHY','Pseudo-Dionysius, The Celestial Hierarchy','Pseudo-Dionysius, The Celestial Hierarchy','Concerning the Principalities, Archangels, and Angels, and concerning their last Hierarchy. SECTION I. THERE remains for our reverent contemplation a Division which completes the Angelic Hierarchies, 1 Dan. ix. 23. m Ezek. x. 2-7. * Dan. viii. 16. 36 Dionysius the Areopagite that divided into the Godlike Principalities, Arch angels, and Angels. And I think it necessary, to declare first the meaning of their sacred appellations to the best of my ability.','John Parker',1897,'https://archive.org/details/theworksofdionys00dionuoft',NULL,'primary-verbatim',NULL,true,'OCR scan, located by name; verify chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CHR_CHERUBIM_DIONYS','ENT_CHR_CHERUBIM','SRC_PSEUDO_DIONYSIUS_CELESTIAL_HIERARCHY','Pseudo-Dionysius, The Celestial Hierarchy','Pseudo-Dionysius, The Celestial Hierarchy','Concerning the Seraphim and Cherubim and Thrones, and concerning their first Hierarchy. SECTION I. WE, whilst admitting this as the arrangement of the holy Hierarchies, affirm, that every appellation of the celestial Minds denotes the Godlike characteristic of each; and those who know Hebrew affirm, that the holy designation of the Seraphim denotes either that they are kindling or burning; and that of Che rubim, a fulness of knowledge or stream of wisdom.','John Parker',1897,'https://archive.org/details/theworksofdionys00dionuoft',NULL,'primary-verbatim',NULL,true,'OCR scan, located by name; verify chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CHR_GUARDIAN_ANGELS_DIONYS','ENT_CHR_GUARDIAN_ANGELS','SRC_PSEUDO_DIONYSIUS_CELESTIAL_HIERARCHY','Pseudo-Dionysius, The Celestial Hierarchy','Pseudo-Dionysius, The Celestial Hierarchy','TRIAD supernal, both sup''er-God and super-good, Guardian of the Theosophy of Christian men, direct us aright to the super-unknown and super-brilliant and highest summit of the mystic Oracles, where the simple and absolute and changeless mysteries of theology lie hidden within the super-luminous gloom of the silence, revealing hidden things, which in its deepest darkness shines above the most super-bril liant, and in the altogether impalpable and invisible,','John Parker',1897,'https://archive.org/details/theworksofdionys00dionuoft',NULL,'primary-verbatim',NULL,true,'OCR scan, located by name; verify chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CHR_POWERS_DIONYS','ENT_CHR_POWERS','SRC_PSEUDO_DIONYSIUS_CELESTIAL_HIERARCHY','Pseudo-Dionysius, The Celestial Hierarchy','Pseudo-Dionysius, The Celestial Hierarchy','42 Dionysius the Areopagite every Hierarchy distributed into first, and middle, and last Powers. But to speak accurately, He dis tinguished each Division itself, by the same Divine harmonies; wherefore the theologians say that the most Divine Seraphim cry one to another b, in dicating distinctly, as I think by this, that the first impart their knowledge of divine things to the second. SECTION III.','John Parker',1897,'https://archive.org/details/theworksofdionys00dionuoft',NULL,'primary-verbatim',NULL,true,'OCR scan, located by name; verify chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CHR_PRINCIPALITIES_DIONYS','ENT_CHR_PRINCIPALITIES','SRC_PSEUDO_DIONYSIUS_CELESTIAL_HIERARCHY','Pseudo-Dionysius, The Celestial Hierarchy','Pseudo-Dionysius, The Celestial Hierarchy','spects the lowest of the Heavenly Hierarchies, the Order of the Angels and Archangels and Principalities is third. CAPUT VII. Concerning the Seraphim and Cherubim and Thrones, and concerning their first Hierarchy. SECTION I.','John Parker',1897,'https://archive.org/details/theworksofdionys00dionuoft',NULL,'primary-verbatim',NULL,true,'OCR scan, located by name; verify chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CHR_SERAPHIM_DIONYS','ENT_CHR_SERAPHIM','SRC_PSEUDO_DIONYSIUS_CELESTIAL_HIERARCHY','Pseudo-Dionysius, The Celestial Hierarchy','Pseudo-Dionysius, The Celestial Hierarchy','Concerning the Seraphim and Cherubim and Thrones, and concerning their first Hierarchy. SECTION I. WE, whilst admitting this as the arrangement of the holy Hierarchies, affirm, that every appellation of the celestial Minds denotes the Godlike characteristic of each; and those who know Hebrew affirm, that the holy designation of the Seraphim denotes either that they are kindling or burning; and that of Che rubim, a fulness of knowledge or stream of wisdom.','John Parker',1897,'https://archive.org/details/theworksofdionys00dionuoft',NULL,'primary-verbatim',NULL,true,'OCR scan, located by name; verify chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CHR_THRONES_DIONYS','ENT_CHR_THRONES','SRC_PSEUDO_DIONYSIUS_CELESTIAL_HIERARCHY','Pseudo-Dionysius, The Celestial Hierarchy','Pseudo-Dionysius, The Celestial Hierarchy','Concerning the Seraphim and Cherubim and Thrones, and concerning their first Hierarchy. SECTION I. WE, whilst admitting this as the arrangement of the holy Hierarchies, affirm, that every appellation of the celestial Minds denotes the Godlike characteristic of each; and those who know Hebrew affirm, that the holy designation of the Seraphim denotes either that they are kindling or burning; and that of Che rubim, a fulness of knowledge or stream of wisdom.','John Parker',1897,'https://archive.org/details/theworksofdionys00dionuoft',NULL,'primary-verbatim',NULL,true,'OCR scan, located by name; verify chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_CHR_VIRTUES_DIONYS','ENT_CHR_VIRTUES','SRC_PSEUDO_DIONYSIUS_CELESTIAL_HIERARCHY','Pseudo-Dionysius, The Celestial Hierarchy','Pseudo-Dionysius, The Celestial Hierarchy','Virtues, Thrones and Seats inaccessible exalt Thee. Splendours of light eternal - mirrors without flaw - holy essences - recipients of wisdom sublime- beyond all, investigators of the will hidden from all, in clearest modulations of inimitable tones, and by voices becoming a rational creature; many eyed Cherubim of most subtle movement, bless Thee. Seraphin, furnished with six wings intertwined, cry Sanctus unto Thee.','John Parker',1897,'https://archive.org/details/theworksofdionys00dionuoft',NULL,'primary-verbatim',NULL,true,'OCR scan, located by name; verify chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_DIO_CELESTIAL_HIERARCHY_DIONYS','ENT_DIO_CELESTIAL_HIERARCHY','SRC_PSEUDO_DIONYSIUS_CELESTIAL_HIERARCHY','Pseudo-Dionysius, The Celestial Hierarchy','Hierarchy 6-9','For sketch of Life, Internal Evidence of date, and External Testimony to genuineness during first nine centuries, see " Celestial and Ecclesiastical Hierarchy." (Skeffington, 25. &amp;/.) DIONYSIUS THE AREOPAGITE ON THE HEAVENLY HIERARCHY. CAPUT I. To MY FELLOW PRESBYTER TIMOTHY*. DIONYSIUS THE PRESBYTER. That every divine illumination, whilst going forth lovingly to the objects of its forethought under various forms, remains simplex. Nor is this all.','John Parker',1897,'https://archive.org/details/theworksofdionys00dionuoft',NULL,'primary-verbatim',NULL,true,'OCR scan, located by name; verify chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
